import logging


def docstring_parameter(*sub):
    """Decorator allowing formatted docstrings"""
    def _fun_with_formated_docstring(obj):
        obj.__doc__ = obj.__doc__.format(*sub)
        return obj
    return _fun_with_formated_docstring


plugin_usage = """
ta_ue_plugin_atcmd doesn't work standalone - it is plugin. You need ute_ue first:
pip install ute_ue
Then ensure plugin is installed as well:
pip install ta_ue_plugin_atcmd
pip list | grep ta-ue
"""

plugin_info = """
AT commands based implementation of Abstract UE (ute_ue library).

This version of plugin supports following functionality:
    - Require Ue keyword to take ue into use from available ues
    - Attach and Detach for UE
    - Data Transfer handling (start, stop and verify throughput)


development project and code repository: https://wrgitlab.int.net.nokia.com/abstract_library/ta_ue_plugin_atcmd

ute_ue JIRA: https://jiradc.int.net.nokia.com/projects/TAUE

ute_ue wiki: https://wrgitlab.int.net.nokia.com/abstract_library/ute_ue/wikis/home

developers mailing list: I_ABSTRACT_LIBRARY_DEV@internal.nsn.com

Ue configuration may be given either as robot variable or environment variable - details see ute_ue documentation.

Demo configuration file examples: see ta_ue_plugin_atcmd/example/config/ folder
or search ta_ue_plugin_atcmd repository for *.yml files

Test Cases examples are available in:
    - ute_ue/example/
    - ta_ue_plugin_atcmd/example/
"""


class ta_ue_plugin_atcmd(object):
    """AT commands based implementation of Abstract UE (ute_ue library)"""

    ROBOT_LIBRARY_SCOPE = 'GLOBAL'

    @docstring_parameter(plugin_usage)
    def show_plugin_usage(self):
        """
        Put into logs usage of this plugin:

        {}

        :return: usage string
        """
        logger = logging.getLogger('ute_ue')
        logger.warning(plugin_usage)
        return plugin_usage

    @docstring_parameter(plugin_info)
    def show_plugin_info(self):
        """
        Put into logs information about this plugin:

        {}

        :return: information string
        """
        logger = logging.getLogger('ute_ue')
        logger.warning(plugin_info)
        return plugin_info


if __name__ == '__main__':
    plugin = ta_ue_plugin_atcmd()
    print(plugin.show_plugin_usage())
    print("------------------------------------")
    print(plugin.show_plugin_info())
    print("------------------------------------")
